blocks.text:
vim.lsp.config('tinymist', {
	cmd = { "tinymist" },
	filetypes = { "typst" },
	settings = {
		exportPdf = "onSave",
	}
})

require('lazy').setup {
	"chomosuke/typst-preview.nvim",
	ft = 'typst',
	version = '~1.4',
}

vim.api.nvim_create_autocmd("FileType", {
	pattern = "typst",
	callback = function(opts)
		if string.match(opts.file, "main.typ$") then
			vim.cmd.TypstPreview("slide")
		end
	end
})
